package com.edward.physicalcraft;
import android.view.View;import android.content.Context;import android.graphics.*;import android.os.SystemClock;

/** Instrument diagrams animate the same numeric value computed by Physics. */
final class ExperimentView extends View {
 final Physics.Mission m;double value;boolean running=false;long began;private final Paint p=new Paint(3);
 ExperimentView(Context c,Physics.Mission m){super(c);this.m=m;value=m.min;setContentDescription("Simulação de "+Physics.NAMES[m.type]);}
 void start(){running=true;began=SystemClock.elapsedRealtime();invalidate();}
 void text(Canvas c,String s,float x,float y,int color){p.setTypeface(Typeface.DEFAULT);p.setTextSize(13);p.setColor(color);c.drawText(s,x,y,p);}
 void line(Canvas c,float x,float y,float X,float Y,int color,float width){p.setColor(color);p.setStrokeWidth(width);c.drawLine(x,y,X,Y,p);}
 void circle(Canvas c,float x,float y,float radius,int color){p.setColor(color);c.drawCircle(x,y,radius,p);}
 void box(Canvas c,float x,float y,float X,float Y,int color){p.setColor(color);c.drawRoundRect(x,y,X,Y,5,5,p);}
 void arrow(Canvas c,float x,float y,float X,float Y,int color){line(c,x,y,X,Y,color,3);double a=Math.atan2(Y-y,X-x);line(c,X,Y,X-(float)Math.cos(a-.5)*10,Y-(float)Math.sin(a-.5)*10,color,3);line(c,X,Y,X-(float)Math.cos(a+.5)*10,Y-(float)Math.sin(a+.5)*10,color,3);}
 @Override protected void onDraw(Canvas c){super.onDraw(c);c.save();c.scale(getWidth()/640f,getHeight()/190f);box(c,0,0,640,190,0xff142e3b);for(int i=20;i<640;i+=25)line(c,i,28,i,165,0x163dcbb8,1);for(int i=40;i<170;i+=25)line(c,15,i,625,i,0x163dcbb8,1);
  double elapsed=running?(SystemClock.elapsedRealtime()-began)/1000.:0;double time=running?elapsed%3:0;float u=(float)(time/3);double output=m.value(value);float fraction=(float)((value-m.min)/(m.max-m.min));int mint=MainActivity.MINT,gold=MainActivity.GOLD,dim=MainActivity.MUTED; text(c,running?"EXPERIMENTO EM CURSO":"AJUSTE → PREVEJA → EXPERIMENTE",16,22,mint);text(c,"Diagrama ilustrativo · modelo ideal",405,22,dim);
  switch(m.type){
   case 0:{line(c,35,145,605,145,dim,2);float x=65+(float)Math.min(475,.5*output*time*time*6);box(c,x,104,x+55,135,mint);circle(c,x+11,140,7,gold);circle(c,x+43,140,7,gold);arrow(c,x+55,114,Math.min(610,x+80+(float)value*1.1f),114,gold);text(c,"F",x+62,101,gold);text(c,"m = "+Physics.fmt(m.parameter)+" kg",42,65,dim);break;}
   case 1:{float top=130-(float)value*2.1f;line(c,400,top,400,155,dim,2);line(c,230,155,520,155,dim,2);float yy=top+(float)Math.min(155-top,.5*9.81*time*time*2.1);circle(c,320,yy,12,mint);text(c,"h = "+Physics.fmt(value)+" m",422,85,gold);text(c,"t = "+Physics.fmt(output)+" s",65,75,mint);break;}
   case 2:{line(c,30,156,610,156,dim,2);float max=(float)Math.max(m.target,output)*1.2f,scale=500/max;float target=60+(float)m.target*scale;box(c,target-10,142,target+10,158,gold);Path path=new Path();for(int i=0;i<=80;i++){double tt=i/80.*Math.sqrt(2)*value/9.81;float xx=60+(float)(value/Math.sqrt(2)*tt)*scale,yy=151-(float)(value/Math.sqrt(2)*tt-4.905*tt*tt)*scale;if(i==0)path.moveTo(xx,yy);else path.lineTo(xx,yy);}p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(2);p.setColor(dim);c.drawPath(path,p);p.setStyle(Paint.Style.FILL);double tt=u*Math.sqrt(2)*value/9.81;circle(c,60+(float)(value/Math.sqrt(2)*tt)*scale,151-(float)(value/Math.sqrt(2)*tt-4.905*tt*tt)*scale,8,mint);text(c,"45° · receptor dourado",35,55,gold);break;}
   case 3:{float top=140-(float)value*3.3f;line(c,70,top,420,150,dim,4);line(c,420,150,600,150,dim,4);circle(c,70+u*350,top+(150-top)*u-9,10,mint);text(c,"mgh → ½mv²",425,65,gold);text(c,"v = "+Physics.fmt(output)+" m/s",420,95,mint);break;}
   case 4:{Path support=new Path();support.moveTo(300,110);support.lineTo(280,155);support.lineTo(320,155);support.close();p.setColor(dim);c.drawPath(support,p);float angle=running?(float)Math.max(-15,Math.min(15,(output-m.target)/3)):0;c.save();c.rotate(angle,300,110);line(c,75,105,555,105,mint,6);float arm=(float)value*44;arrow(c,300-arm,50,300-arm,100,gold);box(c,430,73,480,102,0xff9bb4ba);c.restore();text(c,"20 N · ajuste a distância até o apoio",38,178,dim);break;}
   case 5:{box(c,130,80,510,158,0xff236178);line(c,130,80,510,80,0xff69cad7,2);float yy=running?105-(float)Math.max(-25,Math.min(25,(output-m.target)*.3))*u:105;box(c,285,yy-18,350,yy+18,gold);arrow(c,365,yy,365,yy-40,mint);arrow(c,270,yy,270,yy+35,gold);text(c,"Empuxo ↑     Peso ↓",215,55,dim);break;}
   case 6:{line(c,130,63,510,63,dim,3);line(c,510,63,510,143,dim,3);line(c,510,143,130,143,dim,3);line(c,130,143,130,63,dim,3);box(c,295,52,370,75,gold);line(c,113,90,147,90,mint,4);line(c,120,106,140,106,mint,4);for(int i=0;i<8;i++){float f=(float)((i/8.+time*output*.09)%1);float xx,yy;if(f<.42){xx=130+f/.42f*380;yy=63;}else if(f<.5){xx=510;yy=63+(f-.42f)/.08f*80;}else if(f<.92){xx=510-(f-.5f)/.42f*380;yy=143;}else{xx=130;yy=143-(f-.92f)/.08f*80;}circle(c,xx,yy,4,mint);}text(c,"R = "+Physics.fmt(m.parameter)+" Ω",280,100,gold);break;}
   case 7:{box(c,195,55,445,150,0xff284756);for(int i=0;i<22;i++){double phase=i*2.399+time*Math.sqrt(273+output)*.2;float xx=220+(float)((Math.sin(phase)+1)*100),yy=74+(float)((Math.cos(phase*1.3)+1)*30);circle(c,xx,yy,4,Color.rgb(150+(int)(fraction*100),210-(int)(fraction*90),145));}text(c,"Q = "+Physics.fmt(value)+" kJ",50,90,gold);text(c,"ΔT = "+Physics.fmt(output)+" °C",467,90,mint);break;}
   case 8:{Path wave=new Path();float lambda=(float)output*85;for(int x=30;x<=610;x++){float yy=100+(float)Math.sin((x-30)/lambda*Math.PI*2-time*3)*38;if(x==30)wave.moveTo(x,yy);else wave.lineTo(x,yy);}p.setColor(mint);p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(3);c.drawPath(wave,p);p.setStyle(Paint.Style.FILL);text(c,"λ = "+Physics.fmt(output)+" m",40,164,gold);text(c,"Tempo desacelerado para visualizar",350,164,dim);break;}
   case 9:{line(c,35,105,605,105,dim,1);line(c,320,40,320,165,mint,5);float scale=4,ox=320-(float)value*scale,ix=320+(float)output*scale;float imageH=-(float)(output/value)*38;arrow(c,ox,105,ox,67,gold);line(c,ox,67,320,67,gold,2);line(c,320,67,ix,105-imageH,gold,2);line(c,ox,67,ix,105-imageH,dim,2);arrow(c,ix,105,ix,105-imageH,mint);circle(c,360,105,3,gold);text(c,"objeto",ox-10,55,dim);text(c,"lente",300,183,mint);break;}
   case 10:{float radius=45+fraction*30;circle(c,310,104,25,0xff5ab6b2);p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(1.5f);p.setColor(dim);c.drawOval(310-radius*2,104-radius,310+radius*2,104+radius,p);p.setStyle(Paint.Style.FILL);double ang=time*output*.6;circle(c,310+(float)Math.cos(ang)*radius*2,104+(float)Math.sin(ang)*radius,7,gold);text(c,"r = "+Physics.fmt(value)+" km",45,60,dim);text(c,"v = "+Physics.fmt(output)+" km/s",443,152,mint);break;}
   case 11:{clock(c,215,105,time,dim);clock(c,430,105,time/output,mint);text(c,"Δt · referência",170,171,dim);text(c,"Δτ · em movimento",370,171,mint);text(c,"γ = "+Physics.fmt(output),290,60,gold);break;}
   case 12:{box(c,330,50,347,158,dim);for(int i=0;i<5;i++){float x=40+(float)((time*.65+i*.2)%1)*285;line(c,x,95,x+17,95,gold,3);}if(running&&output>0)for(int i=0;i<5;i++){float x=360+(float)((time*Math.sqrt(output)*.5+i*.2)%1)*230;circle(c,x,80+i*12,4,mint);}text(c,"f = "+Physics.fmt(value)+" THz",38,151,gold);text(c,"Kmáx = "+Physics.fmt(output)+" eV",408,54,mint);break;}
  }
  c.restore();if(running&&isAttachedToWindow())postInvalidateDelayed(33);
 }
 void clock(Canvas c,float x,float y,double time,int color){p.setStyle(Paint.Style.STROKE);p.setColor(color);p.setStrokeWidth(3);c.drawCircle(x,y,45,p);p.setStyle(Paint.Style.FILL);arrow(c,x,y,x+(float)Math.sin(time*2)*33,y-(float)Math.cos(time*2)*33,color);}
}
